import{_ as t,o as a,c as d,a2 as r}from"./chunks/framework.B5aCbeXP.js";const u=JSON.parse('{"title":"API ナビゲーション","description":"","frontmatter":{"lang":"ja","sourcePath":"docs/api.ja.md"},"headers":[],"relativePath":"ja/guide/api.md","filePath":"ja/guide/api.md"}'),o={name:"ja/guide/api.md"};function i(c,e,n,s,h,p){return a(),d("div",null,e[0]||(e[0]=[r('<h1 id="api-ナビゲーション" tabindex="-1">API ナビゲーション <a class="header-anchor" href="#api-ナビゲーション" aria-label="Permalink to &quot;API ナビゲーション&quot;">​</a></h1><blockquote><p>sfml.js は SFML 3.1.0 を基盤としています。手書きのガイドでは使い方、戻り値、Node.js 向けの適応を説明し、完全なシグネチャと型制約は <a href="/ja/reference/" target="_self">TypeDoc</a> がソースコードから生成します。</p></blockquote><p><a href="/ja/guide/">ドキュメントトップ</a> · <a href="/ja/guide/getting-started">クイックスタート</a> · <a href="/ja/guide/concepts">基本概念</a></p><p>公開インターフェースはすべて <code>sfml.js</code> からインポートします。エクスポート一覧は <a href="https://github.com/XadillaX/node-sfml/blob/main/src/index.ts" target="_blank" rel="noreferrer">src/index.ts</a> を参照してください。アプリケーションコードから <code>dist/internal</code> やネイティブモジュールのハンドルにアクセスする必要はありません。</p><h2 id="目的から選ぶ" tabindex="-1">目的から選ぶ <a class="header-anchor" href="#目的から選ぶ" aria-label="Permalink to &quot;目的から選ぶ&quot;">​</a></h2><table tabindex="0"><thead><tr><th>目的</th><th>ドキュメント</th><th>主なインターフェース</th></tr></thead><tbody><tr><td>座標、角度、フレーム時間の計算</td><td><a href="/ja/guide/system">System</a></td><td>Vector2／3、Angle、Time、Clock、名前付き演算関数</td></tr><tr><td>独自のファイルソースの利用</td><td><a href="/ja/guide/system#input-streams">入力ストリーム</a></td><td>InputStream、MemoryInputStream、FileInputStream</td></tr><tr><td>ウィンドウの作成と入力の受信</td><td><a href="/ja/guide/window">Window</a></td><td>RenderWindow、Window、Event、Keyboard、Mouse</td></tr><tr><td>画像とアニメーションの表示</td><td><a href="/ja/guide/graphics">Graphics</a></td><td>Image、Texture、Sprite</td></tr><tr><td>図形とテキストの描画</td><td><a href="/ja/guide/graphics">Graphics</a></td><td>Shape、Font、Glyph、Text</td></tr><tr><td>カメラ、オフスクリーン合成、大量のジオメトリ</td><td><a href="/ja/guide/graphics">Graphics</a></td><td>View、RenderTexture、VertexArray、VertexBuffer</td></tr><tr><td>カスタム描画とシェーダー</td><td><a href="/ja/guide/graphics">Graphics</a></td><td>Drawable、RenderStates、Shader、Glsl</td></tr><tr><td>再生、録音、音声処理</td><td><a href="/ja/guide/audio">Audio</a></td><td>SoundBuffer、Sound、Music、SoundStream、SoundRecorder</td></tr><tr><td>ネットワーク通信とファイル転送</td><td><a href="/ja/guide/network">Network</a></td><td>Packet、TcpSocket、UdpSocket、Http、Ftp、Sftp</td></tr></tbody></table><h2 id="system" tabindex="-1">System <a class="header-anchor" href="#system" aria-label="Permalink to &quot;System&quot;">​</a></h2><p><code>Vector2</code>／<code>Vector3</code> は複数のスカラー型に対応し、<code>Vector2i/u/f</code> と <code>Vector3i/u/f</code> がよく使われる特殊化です。<code>degrees()</code>／<code>radians()</code> で Angle を、時間のファクトリー関数で Time を作成します。</p><p>JavaScript には C++ の演算子オーバーロードがないため、対応する操作には <code>add()</code>、<code>multiply()</code>、<code>equal()</code>、<code>*Assign()</code> を使います。<code>Clock</code>、非同期の <code>sleep()</code>、<code>TimeoutWithPredicate</code>、入力ストリーム、<code>Unicode</code>、エラーログのインターフェースもこのモジュールに含まれます。</p><p>詳細は <a href="/ja/guide/system">System</a> を参照してください。</p><h2 id="window" tabindex="-1">Window <a class="header-anchor" href="#window" aria-label="Permalink to &quot;Window&quot;">​</a></h2><p><code>Window</code> は OS のウィンドウと OpenGL コンテキストを提供します。2D 描画には通常、Window と RenderTarget の両方の機能を持つ <code>RenderWindow</code> を使います。</p><p>イベントは <code>pollEvent()</code>、<code>handleEvents()</code>、同期の <code>waitEvent()</code> で取得できます。キーボード、マウス、ジョイスティック、センサーにはリアルタイムの状態照会もあります。<code>Clipboard</code>、<code>Cursor</code>、<code>Context</code>、<code>Vulkan</code> はシステムとの連携を担います。</p><p>詳細は <a href="/ja/guide/window">Window</a> を参照してください。</p><h2 id="graphics" tabindex="-1">Graphics <a class="header-anchor" href="#graphics" aria-label="Permalink to &quot;Graphics&quot;">​</a></h2><p>Image は CPU 側のピクセル、Texture は GPU テクスチャを保持し、Sprite はテクスチャを参照して描画します。Shape は円、矩形、凸多角形、独自の凸形状を提供します。Font と Text はフォントの読み込み、レイアウト、編集可能な頂点を提供します。</p><p>RenderTarget はウィンドウとオフスクリーンターゲットの描画インターフェースを統一します。View はカメラとビューポートを、RenderStates は変換、ブレンド、ステンシル、テクスチャ、Shader を制御します。頂点配列と GPU 頂点バッファを使えば、ジオメトリを直接構成できます。</p><p>詳細は <a href="/ja/guide/graphics">Graphics</a> と<a href="/ja/guide/concepts#draw-snapshots">描画スナップショット</a>を参照してください。</p><h2 id="audio" tabindex="-1">Audio <a class="header-anchor" href="#audio" aria-label="Permalink to &quot;Audio&quot;">​</a></h2><p>短い効果音には SoundBuffer + Sound、長い音声には Music を使います。SoundSource は音量、パン、空間オーディオのプロパティを提供します。SoundStream、SoundRecorder、EffectProcessor は Worker コールバックで独自のデータを処理します。</p><p>詳細は <a href="/ja/guide/audio">Audio</a> を参照し、特にサンプル数、チャンネルの並び、バッファの有効期間に注意してください。</p><h2 id="network" tabindex="-1">Network <a class="header-anchor" href="#network" aria-label="Permalink to &quot;Network&quot;">​</a></h2><p>Network は Node.js のトランスポートで SFML スタイルの API を実装しており、本番コードは SFML C++ Network を呼び出しません。Packet は SFML のエンコード規約を維持し、TCP、UDP、DNS、TLS、HTTP、FTP、SFTP の I/O には Promise を使います。</p><p>ステータスの戻り値、部分送信、プロトコルの制約、終了方法を含む詳細は <a href="/ja/guide/network">Network</a> を参照してください。</p><h2 id="互換性の範囲" tabindex="-1">互換性の範囲 <a class="header-anchor" href="#互換性の範囲" aria-label="Permalink to &quot;互換性の範囲&quot;">​</a></h2><table tabindex="0"><thead><tr><th>項目</th><th>現在の挙動</th></tr></thead><tbody><tr><td>C++ のポインター、参照による出力引数</td><td>オブジェクト、ビュー、戻り値のオブジェクトで表現</td></tr><tr><td>C++ のテンプレートと演算子</td><td>明示的なスカラータグ、クラス、名前付き関数で表現</td></tr><tr><td>ファイル読み込み</td><td>Promise を使用し、個別の失敗ステータスは各インターフェースに従う</td></tr><tr><td>デストラクター</td><td>ネイティブ側の所有権と JS 参照を組み合わせる。終了用インターフェースを持つリソースは明示的に閉じる</td></tr><tr><td><code>drawAsync()</code>／<code>displayAsync()</code></td><td>未提供。旧サンプルは未対応であることを明示的に報告</td></tr><tr><td>Android SuspendAwareClock</td><td>条件付きコンパイルのインターフェースあり。現在のダウンロードフローはデスクトップ向け</td></tr><tr><td>Vulkan</td><td>照会インターフェースをエクスポート済み。利用可否は SFML のプラットフォームバックエンドに依存し、macOS バックエンドでは利用不可</td></tr></tbody></table><p>プラットフォームごとのビルドとテストの範囲は<a href="/ja/guide/development#testing">開発ガイド</a>を参照してください。</p><p><a id="sfml-cpp-reference"></a></p><h2 id="sfml-c-リファレンス" tabindex="-1">SFML C++ リファレンス <a class="header-anchor" href="#sfml-c-リファレンス" aria-label="Permalink to &quot;SFML C++ リファレンス&quot;">​</a></h2><p><a href="https://www.sfml-dev.org/documentation/3.1.0/" target="_blank" rel="noreferrer">SFML 3.1.0 公式リファレンス</a>は C++ 側の概念を確認するための資料です。JavaScript のシグネチャは <a href="/ja/reference/" target="_self">TypeDoc</a> を基準とし、バインディング固有の挙動は各モジュールのガイドに従ってください。</p><ul><li><a href="/ja/guide/system#sfml-cpp-reference">System の C++ リファレンス</a></li><li><a href="/ja/guide/window#sfml-cpp-reference">Window の C++ リファレンス</a></li><li><a href="/ja/guide/graphics#sfml-cpp-reference">Graphics の C++ リファレンス</a></li><li><a href="/ja/guide/audio#sfml-cpp-reference">Audio の C++ リファレンス</a></li><li><a href="/ja/guide/network#sfml-cpp-reference">Network の C++ リファレンス</a></li></ul>',31)]))}const f=t(o,[["render",i]]);export{u as __pageData,f as default};
